// Original published cartography: never georeferenced or converted into inferred control.
export const territorySources={
 gaza:{label:'Gaza',kind:'Presencia militar y restricciones',date:'2026-07-29',source:'OCHA · reproducción en GOV.UK',url:'https://www.gov.uk/government/publications/palestine-country-policy-and-information-notes/country-policy-and-information-note-humanitarian-situation-in-gaza-palestine-september-2026-accessible-version#map',image:'https://assets.publishing.service.gov.uk/media/6ac4afdbb2822d8ebf1eca24/Gaza_strip_map_29_July_2026.svg',note:'Instantánea de OCHA. No equivale a un reparto completo por bandos ni describe la situación de hoy.'},
 sudan:{label:'Sudán',kind:'Control territorial por bandos',date:'2026-09-25',source:'Sudans Post',url:'https://storage.googleapis.com/qurium/sudanspost.com/territorial-control-map-as-of-september-25-2026.html',image:'https://i0.wp.com/www.sudanspost.com/wp-content/uploads/2026/09/Territorial-Control-map-September-2026-2-scaled.png',note:'Mapa publicado de SAF, RSF y otros grupos según la leyenda original. Corte histórico; no es una capa en tiempo real.'},
 congo:{inline:false,label:'RD del Congo',kind:'Áreas de operación evaluadas',date:'2026-09-25',source:'Critical Threats Project',url:'https://www.criticalthreats.org/briefs/congo-war-security-review/september-25-2026',image:'https://www.criticalthreats.org/wp-content/uploads/20260925-DRC-Main-Map-v2.png',note:'La fuente delimita áreas de operación de AFC-M23. Operación o presencia no significa control territorial exclusivo.'}
};
export function initTerritorySources({esc,host}){
 const root=document.createElement('section');root.id='territory-sources';host.after(root);let previous='';
 return {render({mode,scope,specific}){root.hidden=mode!=='conflicts';if(root.hidden)return;const key=scope+':'+specific;if(key===previous)return;previous=key;
 const keys=specific!=='all'?[specific]:scope==='africa'?['sudan','congo']:scope==='middleEast'?['gaza']:scope==='ukraine'?[]:['gaza','sudan','congo'];
 root.innerHTML=`<details><summary>Control territorial y mapas publicados</summary><p>Ucrania dispone de una capa interactiva VIINA. Los mapas siguientes conservan la leyenda y la fecha de sus autores; no están superpuestos sobre el mapa base de Atlas. Las zonas no clasificadas no se atribuyen a ningún bando.</p>${keys.filter(k=>territorySources[k]).map(k=>{const s=territorySources[k];return `<article><h3>${esc(s.label)} · ${esc(s.kind)}</h3><p><strong>Corte: ${esc(s.date)}</strong> · ${esc(s.source)}. Referencia comprobada el 2026-11-08.</p><p>${esc(s.note)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Fuente y metodología ↗</a>${s.inline===false?'':`<details><summary>Ver mapa original fechado</summary><a href="${esc(s.image)}" target="_blank" rel="noopener noreferrer" aria-label="Ampliar mapa original de ${esc(s.label)}"><img loading="lazy" src="/.netlify/functions/territory-map?map=${k}" alt="Mapa publicado de ${esc(s.label)}; corte ${s.date}. Consulta la leyenda original." referrerpolicy="no-referrer"></a><p class="territory-image-error" hidden>No se pudo cargar la imagen; consulta la fuente enlazada.</p></details>`}</article>`}).join('')||'<p>Sin mapa territorial adicional verificado para esta selección.</p>'}<p>La cobertura territorial no es global. Fuera de las capas documentadas, Atlas mantiene el control como no determinado; los eventos y noticias no se convierten en fronteras.</p></details>`;
 root.querySelectorAll('img').forEach(img=>img.onerror=()=>{img.hidden=true;img.closest('details').querySelector('.territory-image-error').hidden=false;});}};
}
